use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn analyze_syscalls (dir : & str , generate_config : bool) -> Result < () > { println ! ("🔍 Analyzing syscalls in directory: {}" , dir) ; let mut syscall_counts : std :: collections :: HashMap < String , usize > = std :: collections :: HashMap :: new () ; let mut file_count = 0 ; for entry in walkdir :: WalkDir :: new (dir) { let entry = entry ? ; if entry . file_type () . is_file () && entry . path () . extension () . map_or (false , | ext | ext == "rs") { if let Ok (content) = std :: fs :: read_to_string (entry . path ()) { file_count += 1 ; let syscall_patterns = ["std::fs::" , "std::process::" , "std::net::" , "libc::" , "std::time::" , "std::env::" , "std::io::" ,] ; for pattern in & syscall_patterns { let count = content . matches (pattern) . count () ; if count > 0 { * syscall_counts . entry (pattern . to_string ()) . or_insert (0) += count ; } } } } } println ! ("📊 Syscall Analysis Results:") ; println ! ("   Files analyzed: {}" , file_count) ; println ! ("   Syscall patterns found:") ; let mut sorted_syscalls : Vec < _ > = syscall_counts . iter () . collect () ; sorted_syscalls . sort_by (| a , b | b . 1 . cmp (a . 1)) ; for (pattern , count) in & sorted_syscalls { println ! ("     • {}: {} occurrences" , pattern , count) ; } if generate_config && ! syscall_counts . is_empty () { println ! ("\n🔧 Generating targeted interceptor config...") ; let mut interceptor = create_default_syscall_interceptor () ; for (pattern , count) in & sorted_syscalls { if * count > & 10 { println ! ("   Adding high-frequency pattern: {} ({} uses)" , pattern , count) ; } } let json = serde_json :: to_string_pretty (& interceptor) ? ; std :: fs :: write ("analyzed_syscall_config.json" , json) ? ; println ! ("💾 Generated config: analyzed_syscall_config.json") ; } Ok (()) }